# Mini spreadsheet: formulas + dependency recalc (public-domain concept)
import re

class Sheet:
    def __init__(self):
        self.cells = {}
    def set(self, ref, expr):
        self.cells[ref.upper()] = expr
    def get(self, ref, seen=None):
        ref = ref.upper(); seen = seen or set()
        if ref in seen: raise ValueError("circular ref " + ref)
        seen.add(ref)
        v = self.cells.get(ref, 0)
        if isinstance(v, str) and v.startswith("="):
            expr = v[1:]
            expr = re.sub(r"[A-Z]+[0-9]+",
                          lambda m: str(self.get(m.group(0), set(seen))), expr)
            return eval(expr, {"__builtins__": {}})
        return v
    def recalc(self):
        return {r: self.get(r) for r in self.cells}

s = Sheet()
s.set("A1", 1200); s.set("A2", 800); s.set("A3", "=A1+A2")
s.set("B1", 0.15); s.set("B3", "=A3*B1"); s.set("C3", "=A3-B3")
for r, v in s.recalc().items():
    print(f"{r} = {v}")
print("\n1979 magic: change A1, everything depending on it updates.")
